type 'a state = Pending | Resolved of 'a | Rejected of exn
type 'a promise = { mutable state : 'a state; mutable callbacks : ('a state -> unit) list }

let make () = { state = Pending; callbacks = [] }
let return v = { state = Resolved v; callbacks = [] }

let complete p st =
  match p.state with
  | Pending ->
      p.state <- st;
      let cbs = List.rev p.callbacks in
      p.callbacks <- [];
      List.iter (fun cb -> cb st) cbs
  | _ -> invalid_arg "promise already completed"

let resolve p v = complete p (Resolved v)
let reject p e = complete p (Rejected e)

let on_complete p cb =
  match p.state with Pending -> p.callbacks <- cb :: p.callbacks | st -> cb st

let bind p f =
  let q = make () in
  on_complete p (function
    | Resolved v -> (
        match f v with
        | p2 -> on_complete p2 (fun st -> complete q st)
        | exception e -> reject q e)
    | Rejected e -> reject q e
    | Pending -> assert false);
  q

let map f p = bind p (fun v -> return (f v))
let both a b = bind a (fun x -> map (fun y -> (x, y)) b)

let describe show p =
  match p.state with
  | Pending -> "pending"
  | Resolved v -> "resolved " ^ show v
  | Rejected e -> "rejected " ^ Printexc.to_string e

