let rec all = function
  | [] -> return []
  | p :: rest -> bind p (fun x -> bind (all rest) (fun xs -> return (x :: xs)))

let () =
  let ps = [ make (); make (); make () ] in
  let combined = all ps in
  List.iteri (fun i p -> resolve p (10 * (3 - i))) (List.rev ps);
  match combined.state with
  | Resolved l -> print_endline (String.concat "," (List.map string_of_int l))
  | _ -> print_endline "not done"

