let now = ref 0
let seq = ref 0
let queue : (int * int * (unit -> unit)) list ref = ref []

let after delay f =
  incr seq;
  let entry = (!now + delay, !seq, f) in
  queue := List.sort (fun (t1, s1, _) (t2, s2, _) -> compare (t1, s1) (t2, s2)) (entry :: !queue)

let run () =
  let rec loop () =
    match !queue with
    | [] -> ()
    | (time, _, f) :: rest ->
        queue := rest;
        now := time;
        f ();
        loop ()
  in
  loop ()

let log msg = Printf.printf "t=%d %s\n" !now msg
let fetch name k = after (String.length name) (fun () -> k ("content of " ^ name))

let () =
  (* one after another: the delays add up *)
  fetch "a" (fun a ->
      log a;
      fetch "bb" (fun b ->
          log b;
          fetch "ccc" (fun c -> log c; log "sequential done")));
  run ();
  (* all at once: the longest delay decides when everything is done *)
  now := 0;
  let pending = ref 3 in
  let finished content =
    log content;
    decr pending;
    if !pending = 0 then log "all done"
  in
  List.iter (fun name -> fetch name finished) [ "ccc"; "a"; "bb" ];
  run ();
  (* two actions ready at the same time run in the order they were scheduled *)
  now := 0;
  after 5 (fun () -> log "x");
  after 5 (fun () -> log "y");
  run ()

